using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

Console.WriteLine("Research Agent Starting...");

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");

var openAiClient = new OpenAIClient(apiKey);
IChatClient innerClient = openAiClient.GetChatClient("gpt-4o").AsIChatClient();

var notepad = new Notepad();

IChatClient agent = new ChatClientBuilder(innerClient)
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(WebSearchTool.SearchAsync),
        AIFunctionFactory.Create(notepad.AddNote),
        AIFunctionFactory.Create(notepad.GetNotes),
    ]
};

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a given topic thoroughly.
        Use the web_search tool to find information from multiple angles.
        Use the add_note tool to save important findings as you go.
        Perform at least 3 different searches to get broad coverage.
        After researching, use get_notes to review everything you've collected,
        then provide a comprehensive summary of your findings.
        """),
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}")
};

Console.WriteLine($"\nResearching: {topic}\n");

var response = await agent.GetResponseAsync(messages, chatOptions);

Console.WriteLine("=== Research Summary ===\n");
Console.WriteLine(response.Text);
Console.WriteLine("\n=== Collected Notes ===\n");
foreach (var note in notepad.Notes)
{
    Console.WriteLine($"• {note}");
}

// --- Tool Definitions ---

public static class WebSearchTool
{
    private static readonly HttpClient Http = new();

    [Description("Search the web for information on a query. Returns a list of result snippets.")]
    public static async Task<string> SearchAsync(
        [Description("The search query")] string query)
    {
        Console.WriteLine($"  [Search] \"{query}\"");
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var result = await Http.GetFromJsonAsync<JsonElement>(url);

            var snippets = new List<string>();

            if (result.TryGetProperty("AbstractText", out var abs) && abs.GetString() is { Length: > 0 } abstractText)
                snippets.Add($"Summary: {abstractText}");

            if (result.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var item in topics.EnumerateArray().Take(5))
                {
                    if (item.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } t)
                        snippets.Add(t);
                }
            }

            return snippets.Count > 0
                ? string.Join("\n\n", snippets)
                : $"No detailed results found for '{query}'. Try rephrasing the search.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }
}

public class Notepad
{
    public List<string> Notes { get; } = [];

    [Description("Save a research note or finding for later reference.")]
    public string AddNote([Description("The note content to save")] string note)
    {
        Notes.Add(note);
        Console.WriteLine($"  [Note saved] ({Notes.Count} total)");
        return $"Note saved. You now have {Notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (Notes.Count == 0)
            return "No notes saved yet.";
        return string.Join("\n", Notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

